import{_ as d,c as a,o as e,b0 as r}from"./chunks/framework.C5ev1SXp.js";const o="/scm-docs/assets/coresight-path.DQhQIc7R.svg",h="/scm-docs/assets/swd-wiring.DXYvsabe.svg",i="/scm-docs/assets/swd-frame.C5Vc7a7B.svg",s="/scm-docs/assets/dp-ap-access.DJZwSsKG.svg",n="/scm-docs/assets/fpb-breakpoint.BKNIHYpV.svg",D=JSON.parse('{"title":"LV050-SWD调试原理","description":null,"frontmatter":{"title":"LV050-SWD调试原理","date":"2026-11-20T19:14:30.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/dev-tool/debug-and-trace/126d68df2bc630227bd0f1d4","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-11-20T19:14:30.770Z","fulluuid":"27bd0f1d401a4f9bb2762e13651a6b80","useduuid":"27bd0f1d4"}},"headers":[],"relativePath":"sdoc/dev-tool/debug-and-trace/126d68df2bc630227bd0f1d4.md","filePath":"sdoc/01-开发工具/20-调试与跟踪/LV050-SWD调试原理.md","lastUpdated":1795182794000}'),l={name:"sdoc/dev-tool/debug-and-trace/126d68df2bc630227bd0f1d4.md"};function c(p,t,u,b,k,P){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="lv050-swd调试原理" tabindex="-1">LV050-SWD调试原理 <a class="header-anchor" href="#lv050-swd调试原理" aria-label="Permalink to &quot;LV050-SWD调试原理&quot;">​</a></h1><p>前面几篇把&quot;调试手段&quot;当成一份菜单来看（见 <a href="./LV001-调试与跟踪概述.html">LV001-调试与跟踪概述</a>），这篇只拆一道菜：<strong>SWD 到底是什么，为什么两根线就能停住 CPU、读走内存、改掉寄存器</strong>。</p><p>结论先摆在这里：SWD 不是&quot;下载程序的线&quot;，而是一条<strong>独立于 CPU 的总线通道</strong>。程序正常运行、跑飞、甚至卡在 HardFault 里出不来，这条通道照样通。</p><h2 id="一、-swd-在调试体系中的位置" tabindex="-1">一、 SWD 在调试体系中的位置 <a class="header-anchor" href="#一、-swd-在调试体系中的位置" aria-label="Permalink to &quot;一、 SWD 在调试体系中的位置&quot;">​</a></h2><h3 id="_1-它解决的三类问题" tabindex="-1">1. 它解决的三类问题 <a class="header-anchor" href="#_1-它解决的三类问题" aria-label="Permalink to &quot;1. 它解决的三类问题&quot;">​</a></h3><p>大多数人第一次接触 SWD 是为了烧录，于是很容易把它理解成&quot;下载程序的接口&quot;。实际上它承担三件事，而且后两件才是调试的价值所在：</p><p>（1）<strong>下载</strong>：把 hex 写进 Flash。这条路径同样经过 SWD → AHB-AP → Flash 控制器，只是多了一层 Flash 算法（擦除、编程、校验）。</p><p>（2）<strong>控制</strong>：暂停、单步、复位、读写任意地址。这些都是往调试寄存器里写位，不需要目标程序配合。</p><p>（3）<strong>取证</strong>：CPU 已经死掉时读现场。栈、全局变量、外设寄存器全在地址空间里，只要总线还通就能读出来。</p><p>第（3）条是它与 <code>printf</code> 最本质的分界：<code>printf</code> 要求程序还活着，SWD 不要求。</p><h3 id="_2-coresight-的分层" tabindex="-1">2. CoreSight 的分层 <a class="header-anchor" href="#_2-coresight-的分层" aria-label="Permalink to &quot;2. CoreSight 的分层&quot;">​</a></h3><h4 id="_2-1-四层分工" tabindex="-1">2.1 四层分工 <a class="header-anchor" href="#_2-1-四层分工" aria-label="Permalink to &quot;2.1 四层分工&quot;">​</a></h4><p>ARM 把这套体系叫 CoreSight，分层很清楚：</p><table tabindex="0"><thead><tr><th>层次</th><th>组件</th><th>在链路里的角色</th></tr></thead><tbody><tr><td>工具层</td><td>MDK、GDB、OpenOCD</td><td>发起请求、读符号、还原源码行</td></tr><tr><td>传输层</td><td><strong>SWD</strong>、JTAG + 调试探针（J-Link / ST-Link）</td><td>把&quot;寄存器读写&quot;变成两线上的比特流</td></tr><tr><td>访问层</td><td>DAP（DP + AP）、FPB、DWT、ITM</td><td>把&quot;读 0x0800_0000&quot;翻译成总线事务</td></tr><tr><td>内核层</td><td>Cortex-M3</td><td>被观察的对象，本身不参与调试通信</td></tr></tbody></table><p><img src="'+o+'" alt="CoreSight 访问路径：SWD 到总线的四跳"></p><p>图中橙色那格（AHB-AP）是整条链路的分水岭：<strong>它是总线上的一个主设备</strong>，和 CPU 抢同一条总线，而不是&quot;给 CPU 发消息&quot;。</p><h4 id="_2-2-一次反直觉的顺序" tabindex="-1">2.2 一次反直觉的顺序 <a class="header-anchor" href="#_2-2-一次反直觉的顺序" aria-label="Permalink to &quot;2.2 一次反直觉的顺序&quot;">​</a></h4><p>一个常见误解是&quot;调试器在读 CPU 的寄存器，所以要 CPU 配合&quot;。实际顺序是反的：调试器通过 AHB-AP 直接访问 PPB（私有外设总线，<code>0xE000_0000</code> 起）里的调试寄存器，把 CPU 按停；按停之后才去读 R0-R15。</p><p>所以 CPU 被 halt 住、甚至内核锁死（<code>S_LOCKUP</code>），存储器与外设的读写依然成立。这条性质决定了后面所有&quot;现场取证&quot;类操作的前提。</p><h3 id="_3-与-jtag-的关系" tabindex="-1">3. 与 JTAG 的关系 <a class="header-anchor" href="#_3-与-jtag-的关系" aria-label="Permalink to &quot;3. 与 JTAG 的关系&quot;">​</a></h3><h4 id="_3-1-能力等价" tabindex="-1">3.1 能力等价 <a class="header-anchor" href="#_3-1-能力等价" aria-label="Permalink to &quot;3.1 能力等价&quot;">​</a></h4><p>两者在 F1 上共用同一组引脚，由 SWJ-DP 的切换序列决定，能力完全等价：</p><table tabindex="0"><thead><tr><th>维度</th><th>SWD</th><th>JTAG</th></tr></thead><tbody><tr><td>必需引脚</td><td>SWDIO、SWCLK + GND、VTref</td><td>TCK、TMS、TDI、TDO + GND、VTref</td></tr><tr><td>多器件</td><td>一对一</td><td>支持菊花链，一条链上多个芯片</td></tr><tr><td>F1 上的引脚</td><td>PA13、PA14</td><td>PA13~PA15、PB3、PB4</td></tr><tr><td>速率</td><td>4~10 MHz 常见</td><td>与 SWD 同源，可达更高</td></tr><tr><td>调试能力</td><td>相同</td><td>相同</td></tr></tbody></table><h4 id="_3-2-怎么选" tabindex="-1">3.2 怎么选 <a class="header-anchor" href="#_3-2-怎么选" aria-label="Permalink to &quot;3.2 怎么选&quot;">​</a></h4><p>选择几乎没有悬念：<strong>板子引脚紧张就选 SWD</strong>。F103 的 PB3/PB4 常常被别的外设占走，而 JTAG 一开就是五根线；反过来，只有在一条链上串了多颗芯片、必须靠菊花链区分的场合，JTAG 才有不可替代性。</p><h2 id="二、-物理层-两根线怎样完成一次传输" tabindex="-1">二、 物理层：两根线怎样完成一次传输 <a class="header-anchor" href="#二、-物理层-两根线怎样完成一次传输" aria-label="Permalink to &quot;二、 物理层：两根线怎样完成一次传输&quot;">​</a></h2><h3 id="_1-三个角色与接线" tabindex="-1">1. 三个角色与接线 <a class="header-anchor" href="#_1-三个角色与接线" aria-label="Permalink to &quot;1. 三个角色与接线&quot;">​</a></h3><h4 id="_1-1-主机软件、探针、目标" tabindex="-1">1.1 主机软件、探针、目标 <a class="header-anchor" href="#_1-1-主机软件、探针、目标" aria-label="Permalink to &quot;1.1 主机软件、探针、目标&quot;">​</a></h4><p>接线之前先分清三个角色，否则很容易把&quot;SWD&quot;和&quot;J-Link&quot;当成一回事：</p><table tabindex="0"><thead><tr><th>角色</th><th>例子</th><th>职责</th></tr></thead><tbody><tr><td>主机软件</td><td>MDK、GDB、OpenOCD</td><td>下命令、解析符号、显示结果</td></tr><tr><td>调试探针</td><td>J-Link、ST-Link、DAPLink</td><td>把 USB 上的命令翻译成 SWD 时序</td></tr><tr><td>目标</td><td>STM32F103ZE 的 SWJ-DP</td><td>真正执行访问、返回数据</td></tr></tbody></table><p>SWD 描述的是<strong>探针与目标之间那一段</strong>，是 ARM 的公开协议，不属于任何一家探针厂商。所以换探针时，要改的只是接口形态（J-Link 的 20 针排线、ST-Link 的 4 针排针）与速率上限，接线顺序和协议一个字不动。</p><h4 id="_1-2-四根必需线-两根可选" tabindex="-1">1.2 四根必需线，两根可选 <a class="header-anchor" href="#_1-2-四根必需线-两根可选" aria-label="Permalink to &quot;1.2 四根必需线，两根可选&quot;">​</a></h4><p><img src="'+h+'" alt="SWD 接线：探针与目标之间的四根必需线"></p><table tabindex="0"><thead><tr><th>信号</th><th>方向</th><th>目标引脚</th><th>作用</th><th>注意点</th></tr></thead><tbody><tr><td>VTref</td><td>目标 → 探针</td><td>VDD</td><td>电平参考</td><td>只做参考，<strong>不给目标供电</strong>；为 0 时探针判定&quot;未连接&quot;</td></tr><tr><td>GND</td><td>—</td><td>GND</td><td>共地</td><td>至少两根，长线时多点接地</td></tr><tr><td>SWDIO</td><td>双向</td><td>PA13</td><td>数据</td><td>目标内部上拉，外部一般不要再加</td></tr><tr><td>SWCLK</td><td>探针 → 目标</td><td>PA14</td><td>时钟</td><td>目标内部下拉；上升沿采样</td></tr><tr><td>nRESET</td><td>探针 → 目标</td><td>NRST</td><td>复位控制</td><td>可选；接上才能 <code>connect under reset</code></td></tr><tr><td>SWO</td><td>目标 → 探针</td><td>PB3</td><td>ITM 跟踪输出</td><td>可选；只做调试输出，不参与 SWD 传输</td></tr></tbody></table><p>20 针的针脚编号（Pin 1 VTref、Pin 7 SWDIO、Pin 9 SWCLK、Pin 13 SWO、Pin 15 nRESET）来自 ARM 的 Cortex Debug 标准，不是 SEGGER 私有定义——这也是为什么拿一张 ST-Link 的接线图来，除了探针那一端的接口形态，右边部分完全通用。</p><h4 id="_1-3-两个容易踩的点" tabindex="-1">1.3 两个容易踩的点 <a class="header-anchor" href="#_1-3-两个容易踩的点" aria-label="Permalink to &quot;1.3 两个容易踩的点&quot;">​</a></h4><p>（1）<strong>VTref 不是电源</strong>。有些板子把 VTref 当 3.3 V 输入用，结果目标没上电、探针却以为&quot;已连接&quot;，表现在 J-Link 日志里就是反复 <code>Connecting to target via SWD</code> 后失败。</p><p>（2）<strong>PA13/PA14 被复用就没有救</strong>。CubeMX 里把 Debug 从 <code>Serial Wire</code> 改成 <code>Disable</code>、或者把这两脚配成普通 GPIO，芯片一上电就锁死调试口；此时只能靠 <code>connect under reset</code>（复位期间抢占总线）或擦除整片来救。</p><h3 id="_2-一次传输的帧结构" tabindex="-1">2. 一次传输的帧结构 <a class="header-anchor" href="#_2-一次传输的帧结构" aria-label="Permalink to &quot;2. 一次传输的帧结构&quot;">​</a></h3><h4 id="_2-1-三段结构" tabindex="-1">2.1 三段结构 <a class="header-anchor" href="#_2-1-三段结构" aria-label="Permalink to &quot;2.1 三段结构&quot;">​</a></h4><p>SWD 的一次&quot;传输&quot;（transfer）分三段：请求包、应答、数据包。</p><p><img src="'+i+'" alt="SWD 一次传输：请求 8 拍 + 应答 3 拍 + 数据 33 拍"></p><h4 id="_2-2-逐字段含义" tabindex="-1">2.2 逐字段含义 <a class="header-anchor" href="#_2-2-逐字段含义" aria-label="Permalink to &quot;2.2 逐字段含义&quot;">​</a></h4><table tabindex="0"><thead><tr><th>字段</th><th>位数</th><th>驱动方</th><th>含义</th></tr></thead><tbody><tr><td>Start</td><td>1</td><td>主机</td><td>固定为 1</td></tr><tr><td>APnDP</td><td>1</td><td>主机</td><td>0 = 访问 DP，1 = 访问 AP</td></tr><tr><td>RnW</td><td>1</td><td>主机</td><td>0 = 写，1 = 读</td></tr><tr><td>A[3:2]</td><td>2</td><td>主机</td><td>寄存器地址的低两位（地址按字对齐，低两位足够）</td></tr><tr><td>Parity</td><td>1</td><td>主机</td><td>前 4 位的奇偶校验</td></tr><tr><td>Stop</td><td>1</td><td>主机</td><td>固定为 0</td></tr><tr><td>Park</td><td>1</td><td>主机</td><td>固定为 1，用于总线转向</td></tr><tr><td>ACK</td><td>3</td><td>目标</td><td><code>001</code> = OK，<code>010</code> = WAIT，<code>100</code> = FAULT</td></tr><tr><td>Data</td><td>32 + 1</td><td>双向</td><td>数据 + 数据奇偶校验</td></tr></tbody></table><h4 id="_2-3-拍数与校验" tabindex="-1">2.3 拍数与校验 <a class="header-anchor" href="#_2-3-拍数与校验" aria-label="Permalink to &quot;2.3 拍数与校验&quot;">​</a></h4><p>数一下时钟：请求 8 拍、应答 3 拍、数据 33 拍，共 44 拍；再加两次各 1 拍的方向切换，一次完整传输是 <strong>46 个 SWCLK</strong>。4 MHz 下约 11.5 µs 一次——这就是为什么调试器刷内存窗口时你会看到&quot;一屏一屏地刷&quot;，而不是瞬间出现。</p><p>奇偶校验只保护&quot;传输有没有被打断&quot;，不保护数据正确性；真正的可靠性靠 ACK 与协议重试。</p><h4 id="_2-4-应答与错误处理" tabindex="-1">2.4 应答与错误处理 <a class="header-anchor" href="#_2-4-应答与错误处理" aria-label="Permalink to &quot;2.4 应答与错误处理&quot;">​</a></h4><table tabindex="0"><thead><tr><th>应答</th><th>含义</th><th>调试器动作</th></tr></thead><tbody><tr><td>OK</td><td>正常</td><td>继续</td></tr><tr><td>WAIT</td><td>AP 暂时忙：目标在低功耗、或上一次事务还没完成</td><td>自动重试，通常无感</td></tr><tr><td>FAULT</td><td>访问出错：地址非法、权限不够、总线错误</td><td>报错，并把 <code>CTRL/STAT.STICKYERR</code> 置位</td></tr></tbody></table><p><code>STICKYERR</code> 是&quot;粘滞&quot;的：一旦置位不会自己清，必须往 <code>CTRL/STAT</code> 写 1 清除。调试中遇到&quot;突然所有读写都失败&quot;，先清这个位再看，往往就恢复了。</p><h3 id="_3-速率、线缆与连接失败" tabindex="-1">3. 速率、线缆与连接失败 <a class="header-anchor" href="#_3-速率、线缆与连接失败" aria-label="Permalink to &quot;3. 速率、线缆与连接失败&quot;">​</a></h3><h4 id="_3-1-速率的经验值" tabindex="-1">3.1 速率的经验值 <a class="header-anchor" href="#_3-1-速率的经验值" aria-label="Permalink to &quot;3.1 速率的经验值&quot;">​</a></h4><p>SWCLK 的上限受线长与目标约束。经验值：</p><ul><li>20 cm 排线 + F103：4 MHz 稳定，10 MHz 大概率出错</li><li>杜邦线飞线：1 MHz 起步，能跑 4 MHz 算运气好</li><li>连接失败时先降速，再考虑 <code>connect under reset</code></li></ul><h4 id="_3-2-连接失败的四种现象" tabindex="-1">3.2 连接失败的四种现象 <a class="header-anchor" href="#_3-2-连接失败的四种现象" aria-label="Permalink to &quot;3.2 连接失败的四种现象&quot;">​</a></h4><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th><th>处理</th></tr></thead><tbody><tr><td><code>VTref = 0</code></td><td>目标未上电，或 VTref 线没接</td><td>先给目标供电，检查连线</td></tr><tr><td>能连上但一读写就 FAULT</td><td>芯片处于低功耗 / 时钟被关</td><td>改 <code>connect under reset</code>，或先复位</td></tr><tr><td>复位后就再也连不上</td><td>PA13/PA14 被复用作 GPIO</td><td>复位期间抢占总线，改回 <code>Serial Wire</code></td></tr><tr><td>连接时好时坏</td><td>线太长、地线不足、SWCLK 过高</td><td>加地线、降速到 1 MHz 排查</td></tr></tbody></table><h2 id="三、-协议层-dp、ap-与寄存器访问" tabindex="-1">三、 协议层：DP、AP 与寄存器访问 <a class="header-anchor" href="#三、-协议层-dp、ap-与寄存器访问" aria-label="Permalink to &quot;三、 协议层：DP、AP 与寄存器访问&quot;">​</a></h2><h3 id="_1-两个门牌号" tabindex="-1">1. 两个门牌号 <a class="header-anchor" href="#_1-两个门牌号" aria-label="Permalink to &quot;1. 两个门牌号&quot;">​</a></h3><p>SWD 只有两个&quot;门牌号&quot;：DP 和 AP。地址只有两位（A[3:2]），也就是每类最多 4 个寄存器。</p><h4 id="_1-1-dp-四个固定寄存器" tabindex="-1">1.1 DP：四个固定寄存器 <a class="header-anchor" href="#_1-1-dp-四个固定寄存器" aria-label="Permalink to &quot;1.1 DP：四个固定寄存器&quot;">​</a></h4><table tabindex="0"><thead><tr><th>DP 寄存器（APnDP = 0）</th><th>偏移</th><th>作用</th></tr></thead><tbody><tr><td><code>DPIDR</code></td><td>0x00</td><td>只读 ID，F1 上读回 <code>0x1BA01477</code></td></tr><tr><td><code>CTRL/STAT</code></td><td>0x04</td><td>上下电请求、粘滞错误、传输模式</td></tr><tr><td><code>SELECT</code></td><td>0x08</td><td>选哪个 AP（APSEL）、哪个 bank（APBANKSEL）</td></tr><tr><td><code>RDBUFF</code></td><td>0x0C</td><td>读回上一次 AP 读的结果</td></tr></tbody></table><h4 id="_1-2-ap-按-0x1000-展开" tabindex="-1">1.2 AP：按 0x1000 展开 <a class="header-anchor" href="#_1-2-ap-按-0x1000-展开" aria-label="Permalink to &quot;1.2 AP：按 0x1000 展开&quot;">​</a></h4><table tabindex="0"><thead><tr><th>AP 寄存器（APnDP = 1）</th><th>偏移</th><th>作用</th></tr></thead><tbody><tr><td><code>CSW</code></td><td>0x00</td><td>控制：位宽、地址是否自增、保护属性</td></tr><tr><td><code>TAR</code></td><td>0x04</td><td>目标地址</td></tr><tr><td><code>DRW</code></td><td>0x0C</td><td>数据：写 = 发起写，读 = 发起读</td></tr><tr><td><code>BD0</code>~<code>BD3</code></td><td>0x10~0x1C</td><td>bank 里的批量数据寄存器</td></tr></tbody></table><h4 id="_1-3-select-唯一的选路开关" tabindex="-1">1.3 SELECT：唯一的选路开关 <a class="header-anchor" href="#_1-3-select-唯一的选路开关" aria-label="Permalink to &quot;1.3 SELECT：唯一的选路开关&quot;">​</a></h4><p><code>SELECT</code> 是唯一的&quot;路由开关&quot;：<code>APSEL[31:24]</code> 选 AP（0 号是 AHB-AP），<code>APBANKSEL[7:4]</code> 选 bank。忘记切 bank 是读错寄存器最常见的低级原因——地址没错，但读回的是 bank 0 的内容。</p><h3 id="_2-通过-ahb-ap-读内存" tabindex="-1">2. 通过 AHB-AP 读内存 <a class="header-anchor" href="#_2-通过-ahb-ap-读内存" aria-label="Permalink to &quot;2. 通过 AHB-AP 读内存&quot;">​</a></h3><h4 id="_2-1-三步与一次回读" tabindex="-1">2.1 三步与一次回读 <a class="header-anchor" href="#_2-1-三步与一次回读" aria-label="Permalink to &quot;2.1 三步与一次回读&quot;">​</a></h4><p><img src="'+s+`" alt="通过 AHB-AP 读目标内存的三步"></p><p>真实调试器的内部实现大致等价于这几行：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* 访问路径示意：真实调试器在 DAP 内部完成，固件里没有这段代码 */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DP</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SELECT </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">00000000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       /* APSEL = 0（AHB-AP），bank 0 */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AP</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CSW    </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">23000012</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       /* 32 位宽 + 地址自增 */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AP</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TAR    </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">08000000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       /* 想读的目标地址 */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">uint32_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> v </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> AP</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DRW;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          /* 读 DRW：发起一次 AHB 读 */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">v          </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> DP</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">RDBUFF;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       /* 再从 RDBUFF 取回数据 */</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h4 id="_2-2-三个容易弄错的点" tabindex="-1">2.2 三个容易弄错的点 <a class="header-anchor" href="#_2-2-三个容易弄错的点" aria-label="Permalink to &quot;2.2 三个容易弄错的点&quot;">​</a></h4><p>（1）<strong>只有 <code>DRW</code> 产生真正的总线动作</strong>。写 <code>CSW</code>、<code>TAR</code> 只是配置，不产生访问。</p><p>（2）<strong>AP 读是 posted 的</strong>。读 <code>DRW</code> 返回的是&quot;上一次访问&quot;的结果，要想拿到当前值，必须再读 <code>RDBUFF</code>。这就是为什么手写 DAP 代码时&quot;数据总是慢一拍&quot;。</p><p>（3）<strong>地址自增让刷内存变快</strong>。<code>CSW</code> 打开 <code>AddrInc</code> 后，连续读同一块只需写一次 <code>TAR</code>，之后反复读 <code>DRW</code> 即可。MDK 的内存窗口、<code>mem32</code> 命令都是这么干的。</p><h3 id="_3-关键调试寄存器" tabindex="-1">3. 关键调试寄存器 <a class="header-anchor" href="#_3-关键调试寄存器" aria-label="Permalink to &quot;3. 关键调试寄存器&quot;">​</a></h3><h4 id="_3-1-寄存器地图" tabindex="-1">3.1 寄存器地图 <a class="header-anchor" href="#_3-1-寄存器地图" aria-label="Permalink to &quot;3.1 寄存器地图&quot;">​</a></h4><p>这些寄存器都在 PPB 空间，由 AHB-AP 转发访问，地址与 ARM 文档一致：</p><table tabindex="0"><thead><tr><th>寄存器</th><th>地址</th><th>作用</th><th>常用位</th></tr></thead><tbody><tr><td><code>DHCSR</code></td><td>0xE000_EDF0</td><td>调试控制与状态</td><td>C_DEBUGEN、C_HALT、C_STEP、S_HALT</td></tr><tr><td><code>DCRSR</code></td><td>0xE000_EDF4</td><td>选要读写的内核寄存器</td><td>REGSEL[6:0]、REGWnR[16]</td></tr><tr><td><code>DCRDR</code></td><td>0xE000_EDF8</td><td>内核寄存器的数据通道</td><td>与 DCRSR 配对使用</td></tr><tr><td><code>DEMCR</code></td><td>0xE000_EDFC</td><td>调试异常与跟踪总开关</td><td>TRCENA[24]</td></tr><tr><td><code>CPUID</code></td><td>0xE000_ED00</td><td>内核型号</td><td>读回 <code>0x411FC231</code>（Cortex-M3 r1p1）</td></tr><tr><td><code>ICSR</code></td><td>0xE000_ED04</td><td>中断控制与状态</td><td>VECTACTIVE[8:0]</td></tr><tr><td><code>AIRCR</code></td><td>0xE000_ED0C</td><td>复位控制</td><td>SYSRESETREQ[2]、VECTRESET[0]</td></tr></tbody></table><h4 id="_3-2-dhcsr-的写保护" tabindex="-1">3.2 DHCSR 的写保护 <a class="header-anchor" href="#_3-2-dhcsr-的写保护" aria-label="Permalink to &quot;3.2 DHCSR 的写保护&quot;">​</a></h4><p>注意 <code>DHCSR</code> 的写法：高 16 位必须写 <code>0xA05F</code> 作为密钥，否则写入被忽略。这是为了防止程序跑飞后误写调试寄存器。</p><h3 id="_4-一次挂接的五个动作" tabindex="-1">4. 一次挂接的五个动作 <a class="header-anchor" href="#_4-一次挂接的五个动作" aria-label="Permalink to &quot;4. 一次挂接的五个动作&quot;">​</a></h3><p>调试器点&quot;Start Debug Session&quot;时，背后是这么一串动作，串口日志里能看到对应的 J-Link 输出：</p><p>（1）读 <code>DPIDR</code>，确认对端是 SW-DP（本机实测 <code>0x1BA01477</code>）</p><p>（2）扫描 AP，找到 AHB-AP，读 <code>CPUID</code> 确认内核型号（<code>0x411FC231</code> → Cortex-M3 r1p1）</p><p>（3）请求调试电源（<code>CTRL/STAT.CDBGPWRUPREQ</code>），等 <code>CDBGPWRUPACK</code></p><p>（4）置 <code>DHCSR.C_DEBUGEN</code>，按配置决定是否 <code>C_HALT</code></p><p>（5）下载 Flash 算法（若需要烧写），之后才开始正常的断点调试</p><h2 id="四、-调试能力的实现与边界" tabindex="-1">四、 调试能力的实现与边界 <a class="header-anchor" href="#四、-调试能力的实现与边界" aria-label="Permalink to &quot;四、 调试能力的实现与边界&quot;">​</a></h2><h3 id="_1-停机与单步" tabindex="-1">1. 停机与单步 <a class="header-anchor" href="#_1-停机与单步" aria-label="Permalink to &quot;1. 停机与单步&quot;">​</a></h3><p>停机不是&quot;暂停指令&quot;，而是<strong>内核进入调试状态</strong>：取指停止，外设照跑（除非你另外停了它们）。</p><h4 id="_1-1-四个控制位" tabindex="-1">1.1 四个控制位 <a class="header-anchor" href="#_1-1-四个控制位" aria-label="Permalink to &quot;1.1 四个控制位&quot;">​</a></h4><table tabindex="0"><thead><tr><th>位</th><th>名称</th><th>作用</th></tr></thead><tbody><tr><td>0</td><td><code>C_DEBUGEN</code></td><td>调试总使能；不开，任何断点都不会生效</td></tr><tr><td>1</td><td><code>C_HALT</code></td><td>写 1 请求停机，<code>S_HALT</code> 回读确认</td></tr><tr><td>2</td><td><code>C_STEP</code></td><td>与 <code>C_HALT</code> 同时写，执行一条指令后重新停机</td></tr><tr><td>3</td><td><code>C_MASKINTS</code></td><td>单步期间屏蔽可屏蔽中断</td></tr></tbody></table><h4 id="_1-2-单步为什么要屏蔽中断" tabindex="-1">1.2 单步为什么要屏蔽中断 <a class="header-anchor" href="#_1-2-单步为什么要屏蔽中断" aria-label="Permalink to &quot;1.2 单步为什么要屏蔽中断&quot;">​</a></h4><p><code>C_MASKINTS</code> 是个容易被忽略但很关键的位：不屏蔽中断时，单步跨过一条指令后可能先跳进中断服务程序，看起来&quot;单步跑飞了&quot;。MDK 默认会在单步时打开它。</p><h4 id="_1-3-停机的代价" tabindex="-1">1.3 停机的代价 <a class="header-anchor" href="#_1-3-停机的代价" aria-label="Permalink to &quot;1.3 停机的代价&quot;">​</a></h4><p>停机的副作用是<strong>整个系统一起停</strong>：FreeRTOS 的 tick 不再增长，<code>osDelay()</code> 的节拍积压，恢复后会出现一次&quot;补跑&quot;。所以量时序不要用暂停，要用 <a href="./LV004-DWT调试单元.html">LV004-DWT调试单元</a> 里的 <code>CYCCNT</code>。</p><h3 id="_2-断点" tabindex="-1">2. 断点 <a class="header-anchor" href="#_2-断点" aria-label="Permalink to &quot;2. 断点&quot;">​</a></h3><h4 id="_2-1-取指时替换" tabindex="-1">2.1 取指时替换 <a class="header-anchor" href="#_2-1-取指时替换" aria-label="Permalink to &quot;2.1 取指时替换&quot;">​</a></h4><p><img src="`+n+'" alt="硬件断点：FPB 把指令换成 BKPT"></p><p>Cortex-M3 的 FPB（Flash Patch and Breakpoint）有 6 个指令比较器，J-Link 挂接时也明确报告了这一配置：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FPUnit: 6 code (BP) slots and 2 literal slots</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>工作原理是&quot;取指时替换&quot;：地址命中比较器，就把该地址的指令换成 <code>BKPT 0xBE00</code>，内核执行到它就进入调试状态。整个过程不改 Flash 内容——这一点很关键，因为 Flash 里根本改不了。</p><h4 id="_2-2-三种-停-的分工" tabindex="-1">2.2 三种&quot;停&quot;的分工 <a class="header-anchor" href="#_2-2-三种-停-的分工" aria-label="Permalink to &quot;2.2 三种&quot;停&quot;的分工&quot;">​</a></h4><table tabindex="0"><thead><tr><th>手段</th><th>硬件</th><th>数量</th><th>适用</th><th>局限</th></tr></thead><tbody><tr><td>硬件断点</td><td>FPB</td><td>6 个（本机）</td><td>Flash 中的代码</td><td>超出 6 个只能替换或排队</td></tr><tr><td>软件断点</td><td>写入 <code>BKPT</code> 指令</td><td>不限</td><td>RAM 中的代码</td><td>Flash 不可写，用不了</td></tr><tr><td>数据观察点</td><td>DWT</td><td>4 个</td><td>变量/寄存器被读写</td><td>只管数据，不管执行</td></tr></tbody></table><p>F103 的所有代码都在 Flash 里，所以实际能用的是 6 个 FPB 断点。这就是&quot;断点打多了，某些断点莫名其妙不生效&quot;的根本原因。</p><h3 id="_3-观察点与计数器" tabindex="-1">3. 观察点与计数器 <a class="header-anchor" href="#_3-观察点与计数器" aria-label="Permalink to &quot;3. 观察点与计数器&quot;">​</a></h3><p>&quot;谁改了这个变量&quot;只能靠 DWT，细节见 <a href="./LV004-DWT调试单元.html">LV004-DWT调试单元</a>。这里只强调与 SWD 的关系：DWT 的比较器由调试器通过 AHB-AP 配置，命中后由内核产生调试事件；<strong>没有调试器接管时，命中不会停机，也不会进异常</strong>，只是白占一个比较器。</p><h3 id="_4-异常现场" tabindex="-1">4. 异常现场 <a class="header-anchor" href="#_4-异常现场" aria-label="Permalink to &quot;4. 异常现场&quot;">​</a></h3><p>这是 SWD 相对 <code>printf</code> 最有价值的场景：程序已经死了，日志来不及打，但现场还在。</p><h4 id="_4-1-四个-fault-寄存器" tabindex="-1">4.1 四个 Fault 寄存器 <a class="header-anchor" href="#_4-1-四个-fault-寄存器" aria-label="Permalink to &quot;4.1 四个 Fault 寄存器&quot;">​</a></h4><table tabindex="0"><thead><tr><th>寄存器</th><th>地址</th><th>看什么</th></tr></thead><tbody><tr><td><code>CFSR</code></td><td>0xE000_ED28</td><td>三类错误的合并视图（MMFSR / BFSR / UFSR）</td></tr><tr><td><code>HFSR</code></td><td>0xE000_ED2C</td><td><code>FORCED</code>：有异常被升级成 HardFault</td></tr><tr><td><code>MMFAR</code></td><td>0xE000_ED34</td><td>存储器管理错误的地址（配合 <code>MMARVALID</code>）</td></tr><tr><td><code>BFAR</code></td><td>0xE000_ED38</td><td>总线错误的地址（配合 <code>BFARVALID</code>）</td></tr></tbody></table><h4 id="_4-2-从位到结论" tabindex="-1">4.2 从位到结论 <a class="header-anchor" href="#_4-2-从位到结论" aria-label="Permalink to &quot;4.2 从位到结论&quot;">​</a></h4><p><code>CFSR</code> 的非零位直接对应结论：</p><table tabindex="0"><thead><tr><th>位</th><th>名称</th><th>通常意味着</th></tr></thead><tbody><tr><td>BFSR.PRECISERR</td><td>精确总线错误</td><td>访问了非法地址，<code>BFAR</code> 会给出地址</td></tr><tr><td>BFSR.IMPRECISERR</td><td>不精确总线错误</td><td>写缓冲延迟报错，<code>BFAR</code> 无效；加 <code>DSB</code> 或关写缓冲可定位</td></tr><tr><td>BFSR.IBUSERR</td><td>取指总线错误</td><td>PC 跳到了非法区域，通常是函数指针被踩</td></tr><tr><td>UFSR.UNALIGNED</td><td>非对齐访问</td><td>用指针强转结构体做未对齐读写</td></tr><tr><td>UFSR.INVSTATE</td><td>非法状态</td><td>函数指针丢了 Thumb 位（最低位为 0）</td></tr><tr><td>UFSR.UNDEFINSTR</td><td>未定义指令</td><td>数据被当成代码执行，多半是野指针</td></tr></tbody></table><h4 id="_4-3-栈帧里的-pc" tabindex="-1">4.3 栈帧里的 PC <a class="header-anchor" href="#_4-3-栈帧里的-pc" aria-label="Permalink to &quot;4.3 栈帧里的 PC&quot;">​</a></h4><p>异常入栈时 CPU 会自动压入 8 个字：<code>R0 R1 R2 R3 R12 LR PC xPSR</code>。用调试器看 <code>PSP</code> 或 <code>MSP</code> 指向的这块内存，第 6 个字就是出错时的 PC——比在 <code>HardFault_Handler</code> 里加打印快得多。</p><h3 id="_5-跟踪-itm-与-etm" tabindex="-1">5. 跟踪：ITM 与 ETM <a class="header-anchor" href="#_5-跟踪-itm-与-etm" aria-label="Permalink to &quot;5. 跟踪：ITM 与 ETM&quot;">​</a></h3><table tabindex="0"><thead><tr><th>能力</th><th>依赖</th><th>F103 是否可用</th></tr></thead><tbody><tr><td>printf 重定向到 ITM（SWO）</td><td>PB3 引出 + 调试器支持 SWO</td><td>可用（PB3 需空闲）</td></tr><tr><td>事件计数、PC 采样</td><td>DWT</td><td>可用</td></tr><tr><td>完整指令流跟踪</td><td>ETM + TPIU</td><td><strong>不可用</strong>，F103 没有 ETM</td></tr></tbody></table><p>所以 SWD 在 F103 上给的是&quot;现在停在哪、值是多少&quot;，而不是&quot;过去执行了什么&quot;。想要历史，只能靠 DWT 计数器、ITM 事件或外接逻辑分析仪。</p><h3 id="_6-能查什么、查不了什么" tabindex="-1">6. 能查什么、查不了什么 <a class="header-anchor" href="#_6-能查什么、查不了什么" aria-label="Permalink to &quot;6. 能查什么、查不了什么&quot;">​</a></h3><table tabindex="0"><thead><tr><th>想做的事</th><th>SWD 能做到吗</th><th>说明</th></tr></thead><tbody><tr><td>看变量当前值</td><td>能</td><td>只要总线通</td></tr><tr><td>看&quot;刚才发生了什么&quot;</td><td>不能</td><td>无 ETM，没有指令流</td></tr><tr><td>改运行中的变量</td><td>能</td><td>直接写内存，注意一致性</td></tr><tr><td>不打断程序看日志</td><td>需 SWO/RTT</td><td>SWD 本身要停机</td></tr><tr><td>测函数耗时</td><td>需 DWT</td><td>CYCCNT，不依赖停机</td></tr><tr><td>查电源/波形</td><td>不能</td><td>示波器/万用表的活</td></tr></tbody></table><h3 id="_7-与其它手段的分工" tabindex="-1">7. 与其它手段的分工 <a class="header-anchor" href="#_7-与其它手段的分工" aria-label="Permalink to &quot;7. 与其它手段的分工&quot;">​</a></h3><table tabindex="0"><thead><tr><th>手段</th><th>强项</th><th>代价</th><th>代表场景</th></tr></thead><tbody><tr><td>串口 printf</td><td>连续运行也能看，可留档</td><td>占用串口、影响时序</td><td>业务流程、状态机走向</td></tr><tr><td>SWD 停机</td><td>现场完整，CPU 死了也能读</td><td>系统停摆、节拍积压</td><td>HardFault、变量被改、死锁</td></tr><tr><td>DWT</td><td>零侵入、周期级精度</td><td>只有计数与采样，没有现场</td><td>耗时、中断开销</td></tr><tr><td>逻辑分析仪</td><td>真实波形与毛刺</td><td>额外硬件与引脚</td><td>I2C/SPI 时序、复位异常</td></tr></tbody></table><p>四者不可互相替代：SWD 回答&quot;现在是什么状态&quot;，<code>printf</code> 回答&quot;过程是怎么走的&quot;，DWT 回答&quot;花了多少时间&quot;，逻辑分析仪回答&quot;电平到底长什么样&quot;。</p><p>一句话收尾：<strong>SWD 是总线上的第二条命</strong>。它不能告诉你&quot;过去发生了什么&quot;，但只要目标还供电，就能告诉你&quot;现在是什么状态&quot;——而绝大多数嵌入式故障，答案就在&quot;现在&quot;。</p><p>接线检查、MDK 里怎么配、命令行怎么脚本化、以及五个具体的排障场景，见下一篇 <a href="./LV051-SWD调试实践.html">LV051-SWD调试实践</a>。</p><hr><p><em>本文档由 markdowncli 技能辅助生成</em></p>',128)])])}const _=d(l,[["render",c]]);export{D as __pageData,_ as default};
